dictChar = {v: k for k, v in charDict.items()}

def read_u16_le(data, offset) -> int:
    low_byte = data[offset]
    high_byte = data[offset+1]
    return (high_byte << 8) + low_byte

def read_u32_le(data, offset) -> int:
    low_byte = data[offset]
    high_byte = data[offset+1]
    higher_byte = data[offset+2]
    highest_byte = data[offset+3]
    return (highest_byte << 24) + (higher_byte << 16) +(high_byte << 8) + low_byte

def int32_to_byte_list_le(x) -> bytearray:
    byte32_string = "{:08x}".format(x)
    data = bytearray.fromhex(byte32_string)
    data.reverse()
    return data

def int24_to_byte_list_le(x) -> bytearray:
    byte24_string = "{:06x}".format(x)
    data = bytearray.fromhex(byte24_string)
    data.reverse()
    return data

def int16_to_byte_list_le(x) -> bytearray:
    byte32_string = "{:04x}".format(x)
    data = bytearray.fromhex(byte32_string)
    data.reverse()
    return data

def generate_text_bytes(message) -> bytearray:
    return bytearray(char_to_hex(c) for c in message)

def char_to_hex(c) -> int:
    if c in charDict:
        return charDict[c]
    else:
        # If the character doesn't exist, return the star character
        return 0xE4E5

def generate_chip_get(chip, code, amt) -> bytearray:
    chip_bytes = int16_to_byte_list_le(chip)
    byte_list = [0xF4, 0x10, chip_bytes[0], chip_bytes[1], code, amt]
    byte_list.extend(generate_text_bytes("Got a chip for\n\""))
    byte_list.extend([0xFA, 0x00, chip_bytes[0], 0x01 if chip < 256 else 0x02, 0x00, 0xFA, 0x00, code, 0x03])
    byte_list.extend(generate_text_bytes("\"!!"))
    return bytearray(byte_list)

def generate_key_item_get(item, amt) -> bytearray:
    byte_list = [0xF4, 0x00, item, amt]
    byte_list.extend(generate_text_bytes("Got a \n\""))
    byte_list.extend([0xFA, 0x00, item, 0x00])
    byte_list.extend(generate_text_bytes("\"!!"))
    return bytearray(byte_list)

def generate_sub_chip_get(subchip, amt) -> bytearray:
    # SubChips have an extra bit of trouble.
    # If you have too many, they're supposed to skip to another text bank that doesn't give you the item
    # Instead, I'm going to just let it get eaten. Script indices are at a premium and I can't always add one
    byte_list = [0xEF, 0x0A, subchip, amt, 0xFF, 0xFF, 0xFF]
    byte_list.extend(generate_text_bytes("Got a \nSubChip for\n\""))
    byte_list.extend([0xFA, 0x00, subchip, 0x00])
    byte_list.extend(generate_text_bytes("\"!!"))
    return bytearray(byte_list)

def generate_zenny_get(amt) -> bytearray:
    zenny_bytes = int32_to_byte_list_le(amt)
    byte_list = [0xEF, 0x0E, *zenny_bytes, 0xFF, 0xFF, 0xFF]
    byte_list.extend(generate_text_bytes(f"Got \n\"{amt} Zennys\"!!"))
    return bytearray(byte_list)

def generate_program_get(program, color, amt) -> bytearray:
    # Programs are bit shifted twice to generate the "give" bit, essentially multiplying by 4
    byte_list = [0xEF, 0x1B, program << 2, amt, color]
    byte_list.extend(generate_text_bytes("Got a Navi\nCustomizer Program:\n\""))
    byte_list.extend([0xFA, 0x00, program, 0x05])
    return bytearray(byte_list)

def generate_bugfrag_get(amt) -> bytearray:
    frag_bytes = int32_to_byte_list_le(amt)
    byte_list = [0xEF, 0x12, frag_bytes[0], frag_bytes[1], frag_bytes[2], frag_bytes[3], 0xFF, 0xFF, 0xFF]
    byte_list.extend(generate_text_bytes("Got:\n\"" + str(amt) + " BugFrags\"!!"))
    return bytearray(byte_list)

def generate_get_for_item(item) -> bytearray:
    if item.type == ItemType.Chip:
        return generate_chip_get(item.itemID, item.subItemID, item.count)
    elif item.type == ItemType.KeyItem:
        return generate_key_item_get(item.itemID, item.count)
    elif item.type == ItemType.SubChip:
        return generate_sub_chip_get(item.itemID, item.count)
    elif item.type == ItemType.Zenny:
        return generate_zenny_get(item.count)
    elif item.type == ItemType.Program:
        return generate_program_get(item.itemID, item.subItemID, item.count)
    elif item.type == ItemType.BugFrag:
        return generate_bugfrag_get(item.count)

    return generate_text_bytes("Empty Message")

def generate_item_message(item_data) -> bytearray:
    byte_list = [0xF5, 0x01]  # Hide Mugshot
    byte_list.extend([0xE8, 0x00])  # OpenMsg
    byte_list.extend([0xF8, 0x05, 0x18])  # Play Animation
    byte_list.extend(generate_get_for_item(item_data))
    byte_list.extend([0xF8, 0x03]) # Player Finish
    byte_list.extend([0xF8, 0x04]) # PlayerResetScene
    byte_list.extend([0xF8, 0x06]) # PlayerResetObject
    byte_list.extend([0xE7, 0x00]) # keyWait = false
    byte_list.extend([0xF2]) # clearMsg
    return bytearray(byte_list)

# Unfortunately, since mystery data are not handled through text archives normally, we
# have to give a special "key item" that has been renamed to "AP Item" for external items
def generate_external_item_message(item_name, item_recipient) -> bytearray:
    byte_list = [0xF5, 0x01]  # Hide Mugshot
    byte_list.extend([0xE8, 0x00])  # OpenMsg
    byte_list.extend([0xF8, 0x05, 0x18])  # Play Animation
    byte_list = [0xF4, 0x00, 0x37, 0x1]
    byte_list.extend(generate_text_bytes("Got a \n\""))
    byte_list.extend([0xFA, 0x00, 0x3D, 0x00])
    byte_list.extend(generate_text_bytes("\"!!"))
    byte_list.extend([0xF8, 0x03])  # Player Finish
    byte_list.extend([0xF8, 0x04])  # PlayerResetScene
    byte_list.extend([0xF8, 0x06])  # PlayerResetObject
    byte_list.extend([0xE7, 0x00])  # keyWait = false
    byte_list.extend([0xF2])  # clearMsg
    return bytearray(byte_list)

def update_mystery_data(rom_data, offset, type, itemID, subItemID, count) -> bytearray:
    # Reference to the Mystery Data structure: https://forums.therockmanexezone.com/bn4-6-sf1-mystery-data-wave-structure-t5398.html
    # The update address for Mystery Data is the Contents Entry. All we need to update is the type (0x00), the item sub-value (0x03), and the item value (0x04)
    if (type == ItemType.KeyItem):
        # Set the type
        if (itemID == 112):
            # Item = HPMemory
            rom_data[offset] = 0x08
        elif (itemID == 114 or itemID == 115 or itemID == 116):
            # Item = RegUp1, RegUp2, RegUp3
            rom_data[offset] = 0x0A
        if (itemID == 117):
            # Item = SubMemry
            rom_data[offset] = 0x0B
        if (itemID == 113):
            # Item = ExpMemry
            rom_data[offset] = 0x0C
        else:
            # Item = Key Item
            rom_data[offset] = 0x04
        # Set the sub-value. Since we don't need one, use 0xFF
        rom_data[offset + 0x03] = 0xFF
        # Set the item value
        bytes = int32_to_byte_list_le(itemID)
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]
    elif (type == ItemType.Chip):
        # Set the type
        rom_data[offset] = 0x01
        # Set the sub-value.
        rom_data[offset + 0x03] = subItemID
        # Set the item value
        bytes = int32_to_byte_list_le(itemID)
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]
    elif (type == ItemType.SubChip):
        # Set the type
        rom_data[offset] = 0x02
        # Set the sub-value. Since we don't need one, use 0xFF
        rom_data[offset + 0x03] = 0xFF
        # Set the item value
        bytes = int32_to_byte_list_le(itemID)
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]
    elif (type == ItemType.Zenny):
        # Set the type
        rom_data[offset] = 0x03
        # Set the sub-value. Since we don't need one, use 0xFF
        rom_data[offset + 0x03] = 0xFF
        # Set the item value. For Zenny, that's the amount
        bytes = int32_to_byte_list_le(count)
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]
    elif (type == ItemType.BugFrag):
        # Set the type
        rom_data[offset] = 0x05
        # Set the sub-value. Since we don't need one, use 0xFF
        rom_data[offset + 0x03] = 0xFF
        # Set the item value. For BugFrags, that's the amount
        bytes = int32_to_byte_list_le(count)
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]
    elif (type == ItemType.Program):
        # Set the type
        rom_data[offset] = 0x09
        # Set the sub-value.
        rom_data[offset + 0x03] = subItemID
        # Set the item value. For programs, multiply the programID by 4 and add 144
        bytes = int32_to_byte_list_le(144 + (itemID * 4))
        rom_data[offset + 0x04] = bytes[0]
        rom_data[offset + 0x05] = bytes[1]
        rom_data[offset + 0x06] = bytes[2]
        rom_data[offset + 0x07] = bytes[3]

    return rom_data

# For external items, use a specified key item that is renamed to "AP Item"
def update_mystery_data_external(rom_data, offset) -> bytearray:
    # Item = Key Item
    rom_data[offset] = 0x04
    # Set the sub-value. Since we don't need one, use 0xFF
    rom_data[offset + 0x03] = 0xFF
    # Set the item value. For external items, use item ID 61.
    rom_data[offset + 0x04] = 0x3D

    return rom_data